head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gLdMktTp;
scwin.vScrenID = 'ULDSTF15003_ISU.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    dts_isurList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ULDSTF28110_ISUR_LIST";
    dts_isurList.Reset();

    //지수
    var url = "/DsclStdzServiceStatus.do?method=selectIdxIndCd";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_idxIndCd.DataID = encodeURI(url);
    dts_idxIndCd.Reset();
    $c.stf.setObjectValue(rdo_APPL_ISU_BAS_TP_CD, "1");
    scwin.fn_rdoApplIsuBasTpCd_OnSelChange();
};



//종목라디오 버튼 변경시
scwin.fn_rdoApplIsuBasTpCd_OnSelChange = function() {
    //지수
    if ($c.stf.getObjectValue(rdo_APPL_ISU_BAS_TP_CD) == "1") {
        cmb_IND_TP_CD.setDisabled(false); // 업종 selectBox
        cmb_IDX_ID.setDisabled(true); // 지수 selectBox
        dts_isurList.removeAll();
        btn_comSearch.setDisabled(true);
        btn_excelUpload.setDisabled(true); //엑셀업로드
        btn_comDelete.setDisabled(true); //종목삭제

    }
    //발행회사
    else if ($c.stf.getObjectValue(rdo_APPL_ISU_BAS_TP_CD) == "3") {
        $c.stf.setObjectValue(cmb_IND_TP_CD, "");
        $c.stf.setObjectValue(cmb_IDX_ID, "");
        cmb_IND_TP_CD.setDisabled(true); // 업종 selectBox
        cmb_IDX_ID.setDisabled(true); // 지수 selectBox

        dts_isurList.removeAll();
        btn_comSearch.setDisabled(false);
        btn_excelUpload.setDisabled(false); //엑셀업로드
        btn_comDelete.setDisabled(false); //종목삭제

    }
};
scwin.fn_popIsurSearch = async function() {
    //dts_isurList.ClearData();
    await $c.frame.CreateDialogFrame("gform", "/dsclstdz/ULDSTF28112.gfm", "발행회사 검색", 300, 100, 360, 450, "window");
};
scwin.fn_idxIndClick = function() {
    //선택한 지수의 법인리스트
    var url = "/DsclSearchAll.do?method=selectIdxIndIsurList";
    url += "&IDX_ID=" + $c.stf.getObjectValue(cmb_IDX_ID);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_isurList.DataID = encodeURI(url);
    dts_isurList.Reset();
};
scwin.fn_isurDelete = function() {
    if (!scwin.fn_cntDatasetRowCheck(dts_isurList)) {
        $c.win.alert("삭제 할 종목을 선택하여 주십시요");
        return;
    }
    grd_isurList.Redraw = false;
    for (var i = dts_isurList.getTotalRow(); i > 0; i--) {
        if (dts_isurList.getCellData(i, "CHK_FLAG") == 1) {
            $c.cp.removeRow(dts_isurList, i);
        }
    }
    grd_isurList.Redraw = true;
};



/*----------------------------------------------------------------------------
	** 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다. 
-------------------------------------------------------------------------------*/
scwin.fn_cntDatasetRowCheck = function(sval) {
    var cCnt = 0;
    for (i = 1; i <= sval.getTotalRow(); i++) {
        if (sval.getCellData(i, "CHK_FLAG") == 1) {
            cCnt++;
        }
    }
    if (cCnt == 0) {
        return false;
    } else {
        return true;
    }
};
scwin.grd_isurList_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.dts_isurList_OnLoadError = function() {
    $c.stf.alert_error(dts_isurList);
    $c.cm.CloseWin('', grd_isurList);
};
scwin.dts_isurList_OnLoadCompleted = function(rowcount) {
    if (dts_isurList.errorMsg) {
        $c.win.alert("OnLoadCompleted => " + dts_isurList.errorMsg);
    } else {
        $c.cm.CloseWin(rowcount, grd_isurList); //조회완료시 LOADING 이미지 종료

    }
};
scwin.rdo_APPL_ISU_BAS_TP_CD_OnSelChange = function() {
    scwin.fn_rdoApplIsuBasTpCd_OnSelChange();
};
scwin.cmb_IND_TP_CD_OnSelChange = function() {
    dts_idxIndCd.sort("IND_TP_CD", 0);
    //dts_idxIndCd.sort(); // W-Craft 주석처리 
    dts_idxIndCd.UseFilter = true;
    dts_idxIndCd.Filter();
    if ($c.stf.getObjectValue(cmb_IND_TP_CD) != '') {
        cmb_IDX_ID.setDisabled(false);
    }
};
scwin.cmb_IDX_ID_OnSelChange = function() {
    scwin.fn_idxIndClick();
};
scwin.dts_idxIndCd_OnFilter = function(row) {
    //  업종에  해당하는 지수항목을 가져온다.
    var vVal = $c.stf.getObjectValue(cmb_IND_TP_CD);
    if (vVal == "") {
        return true;
    } else {
        var vVal2 = dts_idxIndCd.getCellData(row, "IND_TP_CD");
        return (vVal == vVal2) ? true : false;
    }
};
scwin.btn_ok_onclick = async function() {
    frame.opener.txb_isur_cd.setValue("");
    frame.opener.txb_indTpCd.setValue($c.stf.getObjectValue(cmb_IND_TP_CD));
    frame.opener.txb_idxIndCd.setValue($c.stf.getObjectValue(cmb_IDX_ID));
    if ($c.stf.getObjectValue(rdo_APPL_ISU_BAS_TP_CD) == "1") {
        frame.opener.txb_com_abbrv.setValue($c.cp.valueOfIndex(cmb_IDX_ID, "TEXT", cmb_IDX_ID.getSelectedIndex()));
    } else if ($c.stf.getObjectValue(rdo_APPL_ISU_BAS_TP_CD) == "3") {
        if (dts_isurList.getTotalRow() > 100) {
            $c.win.alert("법인선택은 100개 까지 가능합니다.");
            return;
        }
        var vars = "";
        for (var j = 1; j <= dts_isurList.getTotalRow(); j++) {
            var asNm = dts_isurList.getCellData(j, "COM_ABBRV");
            if (asNm != "") {
                if (j == 1) {
                    vars = asNm;
                } else {
                    vars = vars + "," + asNm;
                }
            }
        }
        frame.opener.txb_com_abbrv.setValue(vars);
        var prt = $c.frame.path("../");
        prt.dts_isurList.ClearData();
        prt.grd_isurList.setBroadcast(false);
        for (var i = dts_isurList.getTotalRow(); i > 0; i--) {
            if (prt.dts_isurList.NameValueRow("ISUR_CD", dts_isurList.getCellData(i, "ISUR_CD")) == 0) {
                prt.dts_isurList.AddRow();
                var aRow = prt.dts_isurList.getTotalRow();
                prt.dts_isurList.setCellData(aRow, "ISUR_CD", dts_isurList.getCellData(i, "ISUR_CD"));
            }
        }
        prt.grd_isurList.setBroadcast(true);
    }
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.btn_excelUpload_onclick = function() {
    var res = window.confirm("엑셀자료를 업로드 하시면 그리드의 내용이 엑셀 데이터로 변경됩니다.");
    if (res) {
        grd_isurList.Redraw = false;
        dts_isurList.removeAll();
        dts_isurList.Do("LoadExcelData", "'','Sheet1',1,0,2");
        for (var i = dts_isurList.getTotalRow(); i > 0; i--) {
            if (dts_isurList.getCellData(i, "ISUR_CD") == "") {
                $c.cp.removeRow(dts_isurList, i);
            }
        }
        grd_isurList.Redraw = true;
    }
};
scwin.btn_excelDownload_onclick = function() {
    location.href = encodeURI("../dsclstdz/excelUploadForm.xls");
};
scwin.btn_comDelete_onclick = function() {
    scwin.fn_isurDelete();
};
scwin.btn_comSearch_onclick = function() {
    scwin.fn_popIsurSearch();
};
scwin.grd_isurList_OnHeadCheckClick = function(col, colid, bCheck) {
    var cnt = dts_isurList.getTotalRow();
    if (cnt > 0) {
        grd_isurList.Redraw = false;
        for (var i = 1; i <= cnt; i++) {
            dts_isurList.setCellData(i, "CHK_FLAG", bCheck);
        }
        grd_isurList.Redraw = true;
    }
};
